package com.voxengine.engine.edge

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.concurrent.Callable
import java.util.concurrent.Executors

class EdgeGecTokenTest {
    @Test
    fun matchesUpstreamV2Vectors() {
        // Generated by rany2/edge-tts drm.py at b2ffbdd9f43f28f03cc939b5de0f3964aa62d60e.
        val vectors = mapOf(
            0L to "52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6",
            300_000L to "F7535A20A262E331-28675BF85C7106BBF20035A78FCB0B6890813EAD5C3B983EF3424931B720BABB",
            1_731_436_500_000L to "3E6B174C66F00BFC-44CFFA409C0572BA0F598EC338578F828BB5159A8741542AC2BFAB84B30579AA",
            1_792_248_600_000L to "67E0BFBBC2A316FF-F881FC475FBA4D8DF0004E6FE47D3B68B9B7EC24959EBBA1D2C1B8D28C589C17",
            1_792_248_900_000L to "DB1F3190E4A03E2E-1ED35778D3F76FD98CA74BFF7C1D79B190C7CB3A2338387DB81C735685924D0F",
            2_147_483_647_000L to "96AE288915A09C99-EB52B45DB68387A1383783E40D42BBBD69D4DCCDF2540629BD4E7FB2E3287822"
        )
        vectors.forEach { (timestamp, expected) ->
            assertEquals("timestamp=$timestamp", expected, EdgeGecToken.generate(timestamp))
        }
    }

    @Test
    fun roundsDownToFiveMinuteWindowsIncludingMilliseconds() {
        val start = 1_792_248_600_000L
        assertEquals(EdgeGecToken.generate(start), EdgeGecToken.generate(start + 299_999))
        assertNotEquals(EdgeGecToken.generate(start), EdgeGecToken.generate(start + 300_000))
    }

    @Test
    fun concurrentRequestsDoNotShareMutableDigestState() {
        val executor = Executors.newFixedThreadPool(4)
        try {
            val timestamps = (0 until 100).map { 1_792_248_600_000L + it * 300_000L }
            val expected = timestamps.map(EdgeGecToken::generate)
            val actual = executor.invokeAll(timestamps.map { timestamp ->
                Callable { EdgeGecToken.generate(timestamp) }
            }).map { it.get() }
            assertEquals(expected, actual)
        } finally {
            executor.shutdownNow()
        }
    }

    @Test
    fun handshakeUsesV2TokenAndBrowserHeaders() {
        val timestamp = 1_792_248_600_000L
        val request = EdgeTTSClient.buildWebSocketRequest(timestamp)
        assertEquals("speech.platform.bing.com", request.url.host)
        assertEquals("/consumer/speech/synthesize/readaloud/edge/v1", request.url.encodedPath)
        assertEquals(EdgeGecToken.TRUSTED_CLIENT_TOKEN, request.url.queryParameter("TrustedClientToken"))
        assertEquals("2-143.0.3650.75", request.url.queryParameter("Sec-MS-GEC-Version"))
        assertEquals(EdgeGecToken.generate(timestamp), request.url.queryParameter("Sec-MS-GEC"))
        assertTrue(request.url.queryParameter("ConnectionId")!!.matches(Regex("[a-f0-9]{32}")))
        assertTrue(request.header("Cookie")!!.matches(Regex("muid=[A-F0-9]{32};")))
        assertEquals("no-cache", request.header("Cache-Control"))
        assertEquals("no-cache", request.header("Pragma"))
        assertEquals("en-US,en;q=0.9", request.header("Accept-Language"))
        assertEquals("chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold", request.header("Origin"))
        assertTrue(request.header("User-Agent")!!.contains("Edg/143.0.0.0"))
    }

    @Test
    fun eachConnectionGetsFreshIdentifiers() {
        val first = EdgeTTSClient.buildWebSocketRequest(0L)
        val second = EdgeTTSClient.buildWebSocketRequest(0L)
        assertNotEquals(first.url.queryParameter("ConnectionId"), second.url.queryParameter("ConnectionId"))
        assertNotEquals(first.header("Cookie"), second.header("Cookie"))
        assertEquals(first.url.queryParameter("Sec-MS-GEC"), second.url.queryParameter("Sec-MS-GEC"))
    }
}
